function WorkflowJourney({onStart}){const ref=useRef(null),[progress,setProgress]=useState(0);useEffect(()=>{const update=()=>{const el=ref.current;if(!el)return;const r=el.getBoundingClientRect(),vh=window.innerHeight;const start=vh*.72,end=-r.height*.18;const raw=(start-r.top)/(start-end);setProgress(Math.max(0,Math.min(1,raw)))};update();window.addEventListener("scroll",update,{passive:true});window.addEventListener("resize",update);return()=>{window.removeEventListener("scroll",update);window.removeEventListener("resize",update)}},[]);const steps=[["01","Upload","Drop in a long-form recording and keep the source organized.",Upload],["02","Understand","Transcribe, detect speakers and surface the strongest moments.",WandSparkles],["03","Select","Review AI-ranked moments and choose the clips worth editing.",Sparkles],["04","Polish","Add captions, hooks, smart reframing, branding and edits.",Scissors],["05","Create","Generate hooks, titles, thumbnails and social copy.",WandSparkles],["06","Publish","Export, schedule and manage the content pipeline.",TrendingUp]];return <div ref={ref} className="workflowJourney" style={{"--journey-progress":progress}}><div className="journeyRail"><i className="journeyRailTrack"/><i className="journeyRailFill"/></div>{steps.map(([n,t,desc,I],i)=>{const active=progress>i/(steps.length-1);return <div className={"workflowCard3d "+(active?"isActive":"")} key={n} onClick={onStart} role="button" tabIndex={0} onKeyDown={e=>{if(e.key==="Enter"||e.key===" ")onStart()}} style={{"--step-delay":(i*.08)+"s"}}><div className="workflowCardNumber">{n}</div><div className="workflowIcon3d"><I size={21}/><span/></div><div className="workflowCardCopy"><h3>{t}</h3><p>{desc}</p></div><ChevronRight className="workflowArrow3d" size={19}/><div className="cardSheen"/></div>})}</div>}

function ProductPreview({onStart}) {
  const ref = useRef(null);
  const [progress, setProgress] = useState(0);
  const windowRef = useRef(null);
  const handleMove = (e) => {
    const el = windowRef.current; if (!el) return;
    const r = el.getBoundingClientRect();
    el.style.setProperty("--px", ((e.clientX - r.left) / r.width - 0.5).toFixed(3));
    el.style.setProperty("--py", ((e.clientY - r.top) / r.height - 0.5).toFixed(3));
  };
  const handleLeave = () => {
    const el = windowRef.current;
    if (el) { el.style.setProperty("--px", 0); el.style.setProperty("--py", 0); }
  };

  useEffect(() => {
    const update = () => {
      const el = ref.current;
      if (!el) return;
      const rect = el.getBoundingClientRect();
      const value = Math.max(0, Math.min(1, (window.innerHeight * 0.9 - rect.top) / (window.innerHeight * 0.75)));
      setProgress(value);
    };
    update();
    window.addEventListener("scroll", update, { passive: true });
    window.addEventListener("resize", update);
    return () => {
      window.removeEventListener("scroll", update);
      window.removeEventListener("resize", update);
    };
  }, []);

  const tilt = 10 - progress * 10;
  const scale = 0.88 + progress * 0.12;
  const lift = 42 - progress * 42;

  return (
    <div
      ref={ref}
      className="productStage"
      onClick={onStart}
      role="button"
      tabIndex={0}
      onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") onStart(); }}
      style={{
        "--preview-progress": progress,
        transform: `translate3d(0,${lift}px,0) scale(${scale})`
      }}
    >
      <div className="stageGlow" />
      <div className="stageFloat">
        <span>AI clip discovery</span><span>12 moments</span><span>94 score</span>
      </div><div className="videoOrbitObjects" aria-hidden="true"><span className="orbitCard orbitOne"><WandSparkles size={16}/><b>AI</b></span><span className="orbitCard orbitTwo"><Scissors size={16}/><b>EDIT</b></span><span className="orbitCard orbitThree"><Sparkles size={16}/><b>HOOK</b></span><span className="orbitCard orbitFour"><CalendarDays size={16}/><b>POST</b></span></div>

      <div className="productWindow" ref={windowRef} onMouseMove={handleMove} onMouseLeave={handleLeave}>
        <div className="windowBar"><span /><span /><span /><b>Alpha.ai / Project workspace</b><span /></div>
        <div className="productBody">
          <aside>
            <div className="miniLogo"><i className="mark" /></div>
            {[BarChart3, FolderKanban, Clapperboard, Scissors, CalendarDays].map((I, i) => (
              <div className={i === 0 ? "miniNav active" : "miniNav"} key={i}><I size={15} /></div>
            ))}
          </aside>

          <div className="mockMain">
            <div className="mockHeader">
              <div><small>PROJECT / PODCAST EP. 24</small><h3>Content overview</h3></div>
              <div className="mockPill"><span /> Processing pipeline</div>
            </div>

            <div className="mockStats">
              <div><small>BEST MOMENT</small><strong>94</strong><span>engagement score</span></div>
              <div><small>CLIP CANDIDATES</small><strong>12</strong><span>AI-selected moments</span></div>
              <div><small>READY TO PUBLISH</small><strong>07</strong><span>edited clips</span></div>
            </div>

            <div className="mockGrid">
              <div className="mockVideo">
                <div className="videoPoster">
                  <div className="posterLines" />
                  <div className="posterAvatar" />
                  <div className="playCircle"><Play size={18} /></div>
                  <span className="duration">00:42</span>
                  <span className="posterTag">BEST MOMENT · 94</span>
                </div>
                <div className="timeline"><span /><i /><i /><i /><i /></div>
                <div className="previewChips"><span>Caption ready</span><span>9:16</span><span>Hook 92%</span></div>
              </div>

              <div className="mockAI">
                <div className="aiTitle"><WandSparkles size={15} /> AI recommendations</div>
                <div className="aiMetric"><div className="aiRow"><span>Hook strength</span><b>92%</b></div><div className="aiBar"><i style={{ width: "92%" }} /></div></div>
                <div className="aiMetric"><div className="aiRow"><span>Share potential</span><b>86%</b></div><div className="aiBar"><i style={{ width: "86%" }} /></div></div>
                <div className="aiMetric"><div className="aiRow"><span>Clarity</span><b>95%</b></div><div className="aiBar"><i style={{ width: "95%" }} /></div></div>
                <div className="aiMiniFeed"><span /><span /><span /><span /></div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

