  const [assistantClips,setAssistantClips]=useState([]),[assistantClipId,setAssistantClipId]=useState(""),[assistantPrompt,setAssistantPrompt]=useState(""),[assistantBusy,setAssistantBusy]=useState(false),[assistantStatus,setAssistantStatus]=useState(""),[assistantError,setAssistantError]=useState("");
