async function handleSourceUrl(url){if(!supabase||!user||!workspace||!url.trim())return;setBusy(true);setProgress(5);setUploadMsg("");let source_type="direct_url";try{const u=new URL(url.trim());const host=u.hostname.toLowerCase();if(host.includes("youtube.com")||host.includes("youtu.be"))source_type="youtube";else if(host.includes("drive.google.com"))source_type="google_drive";else if(host.includes("dropbox.com"))source_type="dropbox";else if(host.includes("1drv.ms")||host.includes("onedrive.live.com"))source_type="onedrive";}catch{setUploadMsg("Please enter a valid URL.");setBusy(false);return}const name=(source_type==="youtube"?"YouTube":source_type==="google_drive"?"Google Drive":source_type==="dropbox"?"Dropbox":source_type==="onedrive"?"OneDrive":"Linked")+" source";const pr=await supabase.from("projects").insert({workspace_id:workspace.id,owner_id:user.id,name,status:"uploading"}).select().single();if(pr.error){setUploadMsg(pr.error.message);setBusy(false);return}const src=await supabase.from("project_sources").insert({workspace_id:workspace.id,project_id:pr.data.id,source_type,source_url:url.trim(),status:"queued",metadata:{url:url.trim()}}).select().single();if(src.error){setUploadMsg(src.error.message);setBusy(false);return}const job=await supabase.from("processing_jobs").insert({workspace_id:workspace.id,project_id:pr.data.id,job_type:"ingest",status:"queued",progress:0,payload:{source_type,source_id:src.data.id,url:url.trim()}}).select().single();if(job.error){setUploadMsg(job.error.message);setBusy(false);return}try{const processingTicket=await getProcessingTicket({workspaceId:workspace.id,projectId:pr.data.id,sourceId:src.data.id,jobId:job.data.id});const response=await fetch("/api/import-source",{method:"POST",headers:{"Content-Type":"application/json","x-import-ticket":processingTicket},body:JSON.stringify({url:url.trim(),sourceType:source_type,workspaceId:workspace.id,projectId:pr.data.id,sourceId:src.data.id,jobId:job.data.id})});const body=await response.json().catch(()=>({}));if(!response.ok){await supabase.from("processing_jobs").update({status:"failed",error:body.error||"Media worker unavailable"}).eq("id",job.data.id);await supabase.from("project_sources").update({status:"failed",error:body.error||"Media worker unavailable"}).eq("id",src.data.id);await supabase.from("projects").update({status:"ingest_failed"}).eq("id",pr.data.id);setUploadMsg(body.error||"The media worker is not connected yet.");setBusy(false);return}}catch(error){console.error(error);setUploadMsg(error?.message||"Could not authorize the processing job.");setBusy(false);return}setProgress(100);setUploadMsg("Link received. The actual video download has started.");await loadProjects(workspace.id);setBusy(false);setTimeout(()=>{setUpload(false);setUploadMsg("")},1200)}

